import{z as d,x as A,o as s,c as B,q as n,j as l,D as t,d as o,s as E,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const x=JSON.parse('{"title":"SSA 析构与 φ 消除","description":"","frontmatter":{"title":"SSA 析构与 φ 消除","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ssa-destruction.md","filePath":"cs/ssa-destruction.md","lastUpdated":1791413859000}'),p={name:"cs/ssa-destruction.md"};function c(C,a,m,S,u,D){const r=A("Mermaid");return s(),B("div",null,[a[2]||(a[2]=n('<h1 id="ssa-析构与-φ-消除" tabindex="-1">SSA 析构与 φ 消除 <a class="header-anchor" href="#ssa-析构与-φ-消除" aria-label="Permalink to &quot;SSA 析构与 φ 消除&quot;">​</a></h1><div class="epigraph"><p>机器没有 φ。析构在每条前驱边末尾插入传送，把 SSA 名合并回可着色的存储。错序会引入交换问题。</p><footer>—— 据 Briggs, Harvey and Simpson, Practical Considerations for SSA Destruction；Cytron et al.；Appel 整理</footer></div><p>上一课<a href="/cs/ssa-construction-cytron">Cytron 构造</a>插入 φ。后端<a href="/cs/regalloc-color">寄存器分配</a>前通常离开 SSA。缺口是<strong>析构</strong>：φ 变成 <code>mov</code>。经典坑：并行 φ 的交换（<code>x,y = y,x</code>）需要临时。本课钉边拷贝与关键边，不写着色。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>φ 语义是「沿进入边同时选择」。实现：在前驱块末 <code>x3 = x1</code> 或 <code>x3 = x2</code>。若同一块两个 φ 交叉赋值，串行 <code>mov</code> 会覆盖。缺口是<strong>并行拷贝的串行化</strong>，不是 DF。</p><p><span class="marginnote">「并行 φ」的坑可以类比成换两杯水：左手橙汁、右手清水，要在不洒的前提下交换——直接倒会混，必须先腾一个空杯。机器指令也是一次只能动一杯，所以 <code>x,y = y,x</code> 必须引入临时 <code>t</code>：<code>t = x; x = y; y = t</code>。编译器漏了这一步，两个变量的值就悄悄变成同一个。</span></p><p>关键边：无唯一插入点，先拆块。</p><h3 id="析构不是「删掉-φ-不管」" tabindex="-1">析构不是「删掉 φ 不管」 <a class="header-anchor" href="#析构不是「删掉-φ-不管」" aria-label="Permalink to &quot;析构不是「删掉 φ 不管」&quot;">​</a></h3><p>随便删 φ 会丢失汇合。必须有拷贝或让分配器同时分配 φ 与操作数到同一寄存器（合并）。</p><p><span class="marginnote">Briggs 等 SSA destruction。Sreedhar 的方法减少拷贝。LLVM 在分配中处理 PHI。本课常规：先拆 φ 再着色，或 SSA 上着色（Chordal）点名。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>拆关键边。为每个 φ 与每个前驱生成拷贝。对块末并行拷贝图：找交换环，用临时或 swap。再跑拷贝传播。</p>',12)),(s(),l(i,null,{default:t(()=>[E(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20PHI%5B%22%CF%86%22%5D%20--%3E%20CRIT%5B%22%E6%8B%86%E5%85%B3%E9%94%AE%E8%BE%B9%22%5D%0A%20%20CRIT%20--%3E%20MOV%5B%22%E5%89%8D%E9%A9%B1%E6%9C%AB%E4%BC%A0%E9%80%81%22%5D%0A%20%20MOV%20--%3E%20SER%5B%22%E5%B9%B6%E8%A1%8C%E6%8B%B7%E8%B4%9D%E4%B8%B2%E8%A1%8C%E5%8C%96%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[o("与"),e("a",{href:"/cs/coalescing-splitting"},"合并"),o(" 后课：析构产生的 "),e("code",null,"mov"),o(" 正是合并的输入。")],-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"关键边翻译一下：一条「上游分岔、下游汇合」的边——上游还有别的出口、下游还有别的入口，所以这条边自己没有「末尾」可放指令。解决办法是把它劈成两段，中间凭空造一个空块，指令就放进那个空块里。不先拆边，φ 的拷贝要么放不进去，要么会被上游的其他后继错误地执行到。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[o("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"未定义的 φ 操作数（未初始化变量）须按语言填毒值或拒绝。不要在析构后还当 SSA 做 SCCP。",-1)),a[7]||(a[7]=e("p",null,"异常边：前驱是 invoke 的 unwind，插入点在专用边块。",-1)),(s(),l(i,null,{default:t(()=>[E(r,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20PAIR%5B%22%E5%B9%B6%E8%A1%8C%20%CF%86%EF%BC%9Ax%2Cy%20%3D%20y%2Cx%22%5D%20--%3E%20NAIVE%5B%22%E7%9B%B4%E6%8E%A5%E4%B8%B2%E8%A1%8C%EF%BC%9A%E5%85%88%20x%20%3D%20y%22%5D%0A%20%20NAIVE%20--%3E%20WRONG%5B%22x%20%E7%9A%84%E6%97%A7%E5%80%BC%E5%B7%B2%E8%A2%AB%E8%A6%86%E7%9B%96%EF%BC%8C%E8%AF%AD%E4%B9%89%E9%94%99%22%5D%0A%20%20PAIR%20--%3E%20TEMP%5B%22%E5%BC%95%E5%85%A5%E4%B8%B4%E6%97%B6%20t%20%E4%BF%9D%E5%AD%98%E4%B8%80%E4%B8%AA%E6%BA%90%22%5D%0A%20%20TEMP%20--%3E%20ORDER%5B%22x%20%3D%20y%20%E5%86%8D%20y%20%3D%20t%EF%BC%8C%E5%90%84%E8%AF%BB%E5%90%84%E7%9A%84%E6%BA%90%22%5D%0A%20%20ORDER%20--%3E%20RIGHT%5B%22%E7%BB%93%E6%9E%9C%E7%AD%89%E4%BA%8E%E5%90%8C%E6%97%B6%E8%B5%8B%E5%80%BC%EF%BC%8C%E8%AF%AD%E4%B9%89%E6%AD%A3%E7%A1%AE%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=n('<p><span class="marginnote">初学者容易以为析构产生的 <code>mov</code> 会原样留在最终机器码里、白白变慢。实际上这些拷贝正是后课「合并」的原料：分配器把源与目标分到同一寄存器，<code>mov</code> 就消失了。析构的职责只是「语义正确地降级」，优化交给后面的阶段——这也是「先析构再着色」这条流水线的分工。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 Briggs 着色。后课默认：φ 在后端前变成传送。后课自然循环：许多循环优化要在 SSA 上认循环，构造/析构顺序是「优化在 SSA，分配前析构」。</p><p>也不把析构当 DCE。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>析构：φ → 前驱边拷贝；关键边先拆。</li><li>并行赋值要处理交换。</li><li>与随后的合并、着色衔接。</li><li>出处：Cytron et al.；Briggs, Harvey and Simpson；Appel。</li></ul>',6))])}const f=d(p,[["render",c]]);export{x as __pageData,f as default};
